import { ProfilePatch } from './types';

export function parseProfile(input: unknown): ProfilePatch {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) {
    throw new Error('invalid profile');
  }
  const prototype = Object.getPrototypeOf(input);
  if (prototype !== Object.prototype && prototype !== null) {
    throw new Error('invalid profile');
  }
  for (const key of Reflect.ownKeys(input)) {
    if (key !== 'displayName' && key !== 'tags') throw new Error('invalid profile');
  }

  const fields = input as Record<string, unknown>;
  let displayName: ProfilePatch['displayName'] = { kind: 'keep' };
  let tags: ProfilePatch['tags'] = { kind: 'keep' };
  if (Object.prototype.hasOwnProperty.call(input, 'displayName')) {
    const value = fields.displayName;
    if (value === null) {
      displayName = { kind: 'set', value: null };
    } else {
      if (typeof value !== 'string') throw new Error('invalid profile');
      const trimmed = value.trim();
      if (trimmed.length < 1 || trimmed.length > 40) throw new Error('invalid profile');
      displayName = { kind: 'set', value: trimmed };
    }
  }
  if (Object.prototype.hasOwnProperty.call(input, 'tags')) {
    const value = fields.tags;
    if (value === null) {
      tags = { kind: 'set', value: [] };
    } else {
      if (!Array.isArray(value) || value.length > 5) throw new Error('invalid profile');
      const strings: string[] = [];
      const seen = new Set<string>();
      for (const tag of value) {
        if (typeof tag !== 'string') throw new Error('invalid profile');
        const trimmed = tag.trim();
        if (trimmed.length < 1 || trimmed.length > 12 || seen.has(trimmed)) {
          throw new Error('invalid profile');
        }
        seen.add(trimmed);
        strings.push(trimmed);
      }
      tags = { kind: 'set', value: strings };
    }
  }
  return { displayName, tags };
}

